                    int newPrev = (prev * 10 + j) % 25;
                    res += solve(A, idx + 1, newPrev, j);
                }
            }
        } else {
            int digit = A[idx] - '0';
            res += solve(A, idx + 1, (prev * 10 + digit) % 25, v);
        }
        return cache[idx][prev][v] = res;
    }
