import sys
sys.setrecursionlimit(10**7)

MOD = 998244353

def main():
    T = 1
    for _ in range(T):
        s = input().strip()
        A = list(s)
        if len(A) == 1 and A[0] == '0':
            print("1")
            return
        if A[0] == '0':
            print("0")
            return
        if len(A) == 1 and (A[0] == 'X' or A[0] == '_'):
            print("1")
            return
        cache = [[[-1 for _ in range(11)] for _ in range(25)] for _ in range(len(A)+1)]

        def solve(idx, prev, v):
            if idx == len(A):
                return 1 if prev == 0 else 0
            if cache[idx][prev][v] != -1:
                return cache[idx][prev][v]
            res = 0
            if A[idx] == '_':
                for j in range(10):
                    if idx == 0 and j == 0:
                        continue
                    newPrev = (prev * 10 + j) % 25
                    res += solve(idx + 1, newPrev, v)
            elif A[idx] == 'X':
                if v != 10:
                    res += solve(idx + 1, (prev * 10 + v) % 25, v)
                else:
                    for j in range(10):
                        if idx == 0 and j == 0:
                            continue
                        newPrev = (prev * 10 + j) % 25
                        res += solve(idx + 1, newPrev, j)
            else:
                digit = int(A[idx])
                res += solve(idx + 1, (prev * 10 + digit) % 25, v)
            cache[idx][prev][v] = res
            return res

        print(solve(0, 0, 10))

if __name__ == "__main__":
    main()

